[metadata] {"type": "create", "filePath": "/app/output/index.html", "content": "<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>Page Not Found — IdeaForum</title>
  <link rel="preconnect" href="https://fonts.googleapis.com" />
  <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin />
  <link href="https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500;600;700&display=swap" rel="stylesheet" />
  <style>
    *, *::before, *::after {
      box-sizing: border-box;
      margin: 0;
      padding: 0;
    }

    :root {
      --brand-red: #EB0028;
      --text-primary: #121212;
      --text-secondary: #555555;
      --text-muted: #777777;
      --text-light: #999999;
      --bg-white: #FFFFFF;
      --bg-subtle: #F5F5F5;
      --bg-error-bar: #F0F0F0;
      --border-color: #DEDEDE;
      --font: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
    }

    html, body {
      height: 100%;
    }

    body {
      font-family: var(--font);
      background-color: var(--bg-white);
      color: var(--text-primary);
      min-height: 100vh;
      display: flex;
      flex-direction: column;
      -webkit-font-smoothing: antialiased;
      -moz-osx-font-smoothing: grayscale;
    }

    /* ── Main content ── */
    .page-wrapper {
      flex: 1;
      display: flex;
      flex-direction: column;
      align-items: center;
      justify-content: center;
      padding: 60px 24px 120px;
    }

    .content-container {
      width: 100%;
      max-width: 560px;
      display: flex;
      flex-direction: column;
      align-items: center;
      gap: 0;
    }

    /* ── Logo ── */
    .logo-section {
      margin-bottom: 52px;
      text-align: center;
    }

    .logo {
      display: inline-flex;
      align-items: center;
      gap: 0;
      text-decoration: none;
      line-height: 1;
    }

    .logo-svg {
      width: auto;
      height: 52px;
    }

    /* ── Error message ── */
    .error-message-section {
      text-align: center;
      margin-bottom: 32px;
      width: 100%;
    }

    .apology {
      font-size: 28px;
      font-weight: 600;
      color: var(--text-primary);
      letter-spacing: -0.02em;
      line-height: 1.2;
      margin-bottom: 12px;
    }

    .suggestion {
      font-size: 15px;
      font-weight: 400;
      color: var(--text-secondary);
      line-height: 1.6;
    }

    /* ── Search ── */
    .search-section {
      width: 100%;
      margin-bottom: 28px;
    }

    .search-form {
      position: relative;
      width: 100%;
    }

    .search-input {
      width: 100%;
      height: 50px;
      padding: 0 52px 0 16px;
      font-family: var(--font);
      font-size: 15px;
      font-weight: 400;
      color: var(--text-primary);
      background: var(--bg-white);
      border: 1.5px solid var(--border-color);
      border-radius: 6px;
      outline: none;
      transition: border-color 0.15s ease, box-shadow 0.15s ease;
      appearance: none;
      -webkit-appearance: none;
    }

    .search-input::placeholder {
      color: var(--text-light);
    }

    .search-input:focus {
      border-color: #AAAAAA;
      box-shadow: 0 0 0 3px rgba(0, 0, 0, 0.06);
    }

    .search-btn {
      position: absolute;
      right: 0;
      top: 0;
      bottom: 0;
      width: 50px;
      display: flex;
      align-items: center;
      justify-content: center;
      background: transparent;
      border: none;
      border-left: 1.5px solid var(--border-color);
      cursor: pointer;
      color: var(--text-muted);
      border-radius: 0 6px 6px 0;
      transition: background 0.15s ease, color 0.15s ease;
    }

    .search-btn:hover {
      background: var(--bg-subtle);
      color: var(--text-primary);
    }

    .search-btn:focus-visible {
      outline: 2px solid var(--text-primary);
      outline-offset: 2px;
      border-radius: 0 4px 4px 0;
    }

    .search-btn svg {
      width: 18px;
      height: 18px;
      flex-shrink: 0;
    }

    /* ── Error code bar ── */
    .error-code-section {
      width: 100%;
      margin-bottom: 28px;
    }

    .error-code-bar {
      width: 100%;
      padding: 12px 16px;
      background: var(--bg-error-bar);
      border-radius: 4px;
      text-align: left;
    }

    .error-code-text {
      font-size: 13px;
      font-weight: 400;
      color: var(--text-muted);
      letter-spacing: 0.01em;
    }

    .section-divider {
      width: 100%;
      height: 1px;
      background: var(--border-color);
      margin-top: 28px;
    }

    /* ── Next steps ── */
    .next-steps-section {
      width: 100%;
      padding-top: 28px;
    }

    .next-steps-heading {
      font-size: 13px;
      font-weight: 600;
      color: var(--text-primary);
      text-transform: uppercase;
      letter-spacing: 0.08em;
      margin-bottom: 16px;
    }

    .nav-links {
      display: flex;
      flex-direction: column;
      gap: 10px;
    }

    .nav-link {
      font-size: 15px;
      font-weight: 400;
      color: var(--text-muted);
      text-decoration: underline;
      text-underline-offset: 3px;
      text-decoration-color: transparent;
      transition: color 0.15s ease, text-decoration-color 0.15s ease;
    }

    .nav-link:hover {
      color: var(--text-primary);
      text-decoration-color: var(--text-primary);
    }

    .nav-link:focus-visible {
      outline: 2px solid var(--text-primary);
      outline-offset: 3px;
      border-radius: 2px;
    }

    /* ── Cookie banner ── */
    .cookie-banner {
      position: fixed;
      bottom: 0;
      left: 0;
      right: 0;
      background: var(--text-primary);
      color: #CCCCCC;
      padding: 18px 24px;
      display: flex;
      align-items: center;
      gap: 20px;
      z-index: 100;
      transform: translateY(0);
      transition: transform 0.3s ease;
    }

    .cookie-banner.hidden {
      transform: translateY(110%);
    }

    .cookie-banner-text {
      flex: 1;
      font-size: 13px;
      line-height: 1.6;
      color: #BBBBBB;
    }

    .cookie-privacy-link {
      color: #DDDDDD;
      text-decoration: underline;
      text-underline-offset: 2px;
      transition: color 0.15s ease;
    }

    .cookie-privacy-link:hover {
      color: #FFFFFF;
    }

    .cookie-banner-actions {
      display: flex;
      align-items: center;
      gap: 12px;
      flex-shrink: 0;
    }

    .btn-manage {
      font-family: var(--font);
      font-size: 13px;
      font-weight: 500;
      color: var(--text-primary);
      background: #FFFFFF;
      border: none;
      border-radius: 4px;
      padding: 8px 16px;
      cursor: pointer;
      white-space: nowrap;
      transition: background 0.15s ease;
    }

    .btn-manage:hover {
      background: #E8E8E8;
    }

    .btn-manage:focus-visible {
      outline: 2px solid #FFFFFF;
      outline-offset: 2px;
    }

    .btn-dismiss {
      font-family: var(--font);
      font-size: 13px;
      font-weight: 400;
      color: #999999;
      background: transparent;
      border: none;
      cursor: pointer;
      padding: 4px;
      line-height: 1;
      transition: color 0.15s ease;
    }

    .btn-dismiss:hover {
      color: #FFFFFF;
    }

    /* ── Preferences modal ── */
    .modal-overlay {
      position: fixed;
      inset: 0;
      background: rgba(0, 0, 0, 0.45);
      z-index: 200;
      display: flex;
      align-items: center;
      justify-content: center;
      padding: 24px;
      opacity: 0;
      pointer-events: none;
      transition: opacity 0.2s ease;
    }

    .modal-overlay.active {
      opacity: 1;
      pointer-events: auto;
    }

    .modal {
      background: var(--bg-white);
      border-radius: 8px;
      width: 100%;
      max-width: 520px;
      max-height: 90vh;
      overflow-y: auto;
      padding: 36px;
      box-shadow: 0 20px 60px rgba(0, 0, 0, 0.2);
      transform: translateY(8px);
      transition: transform 0.2s ease;
    }

    .modal-overlay.active .modal {
      transform: translateY(0);
    }

    .modal-header {
      display: flex;
      align-items: flex-start;
      justify-content: space-between;
      margin-bottom: 24px;
      gap: 16px;
    }

    .modal-title {
      font-size: 20px;
      font-weight: 600;
      color: var(--text-primary);
      letter-spacing: -0.01em;
    }

    .modal-close {
      background: transparent;
      border: none;
      cursor: pointer;
      color: var(--text-muted);
      padding: 4px;
      border-radius: 4px;
      display: flex;
      align-items: center;
      transition: color 0.15s ease, background 0.15s ease;
      flex-shrink: 0;
    }

    .modal-close:hover {
      color: var(--text-primary);
      background: var(--bg-subtle);
    }

    .modal-close:focus-visible {
      outline: 2px solid var(--text-primary);
      outline-offset: 2px;
    }

    .modal-close svg {
      width: 20px;
      height: 20px;
    }

    .modal-description {
      font-size: 14px;
      color: var(--text-secondary);
      line-height: 1.65;
      margin-bottom: 28px;
    }

    .pref-list {
      display: flex;
      flex-direction: column;
      gap: 0;
      border: 1px solid var(--border-color);
      border-radius: 6px;
      overflow: hidden;
      margin-bottom: 28px;
    }

    .pref-item {
      display: flex;
      align-items: flex-start;
      justify-content: space-between;
      gap: 20px;
      padding: 20px;
      border-bottom: 1px solid var(--border-color);
    }

    .pref-item:last-child {
      border-bottom: none;
    }

    .pref-label-group {
      flex: 1;
    }

    .pref-label {
      font-size: 14px;
      font-weight: 500;
      color: var(--text-primary);
      margin-bottom: 4px;
    }

    .pref-desc {
      font-size: 13px;
      color: var(--text-secondary);
      line-height: 1.55;
    }

    /* Toggle switch */
    .toggle-wrapper {
      flex-shrink: 0;
      display: flex;
      align-items: center;
      gap: 8px;
    }

    .toggle-label {
      font-size: 12px;
      color: var(--text-muted);
    }

    .toggle {
      position: relative;
      width: 40px;
      height: 22px;
    }

    .toggle input {
      opacity: 0;
      width: 0;
      height: 0;
      position: absolute;
    }

    .toggle-track {
      position: absolute;
      cursor: pointer;
      inset: 0;
      background: #D0D0D0;
      border-radius: 22px;
      transition: background 0.2s ease;
    }

    .toggle input:checked + .toggle-track {
      background: var(--text-primary);
    }

    .toggle input:disabled + .toggle-track {
      opacity: 0.5;
      cursor: not-allowed;
    }

    .toggle-track::before {
      content: '';
      position: absolute;
      width: 16px;
      height: 16px;
      left: 3px;
      top: 3px;
      background: white;
      border-radius: 50%;
      transition: transform 0.2s ease;
    }

    .toggle input:checked + .toggle-track::before {
      transform: translateX(18px);
    }

    .toggle input:focus-visible + .toggle-track {
      outline: 2px solid var(--text-primary);
      outline-offset: 2px;
    }

    .modal-footer {
      display: flex;
      align-items: center;
      justify-content: flex-end;
      gap: 12px;
    }

    .btn-secondary {
      font-family: var(--font);
      font-size: 14px;
      font-weight: 400;
      color: var(--text-secondary);
      background: transparent;
      border: 1.5px solid var(--border-color);
      border-radius: 5px;
      padding: 9px 20px;
      cursor: pointer;
      transition: border-color 0.15s ease, color 0.15s ease;
    }

    .btn-secondary:hover {
      border-color: #AAAAAA;
      color: var(--text-primary);
    }

    .btn-primary {
      font-family: var(--font);
      font-size: 14px;
      font-weight: 500;
      color: #FFFFFF;
      background: var(--text-primary);
      border: none;
      border-radius: 5px;
      padding: 9px 20px;
      cursor: pointer;
      transition: background 0.15s ease;
    }

    .btn-primary:hover {
      background: #2A2A2A;
    }

    .btn-primary:focus-visible,
    .btn-secondary:focus-visible {
      outline: 2px solid var(--text-primary);
      outline-offset: 2px;
    }

    /* ── Responsive ── */
    @media (max-width: 600px) {
      .page-wrapper {
        padding: 48px 20px 110px;
        justify-content: flex-start;
        padding-top: 64px;
      }

      .logo-section {
        margin-bottom: 40px;
      }

      .logo-svg {
        height: 42px;
      }

      .apology {
        font-size: 22px;
      }

      .cookie-banner {
        flex-direction: column;
        align-items: flex-start;
        gap: 14px;
        padding: 16px 20px;
      }

      .cookie-banner-actions {
        width: 100%;
        justify-content: flex-end;
      }

      .modal {
        padding: 24px;
      }

      .pref-item {
        flex-direction: column;
        gap: 12px;
      }

      .toggle-wrapper {
        align-self: flex-start;
      }

      .modal-footer {
        flex-direction: column-reverse;
        gap: 10px;
      }

      .btn-secondary,
      .btn-primary {
        width: 100%;
        text-align: center;
      }
    }

    @media (min-width: 601px) and (max-width: 900px) {
      .page-wrapper {
        padding: 72px 40px 120px;
      }
    }
  </style>
</head>
<body>

  <!-- ═══════════════════════════ MAIN PAGE ═══════════════════════════ -->
  <main class="page-wrapper" role="main">
    <div class="content-container">

      <!-- Hero Logo -->
      <header class="logo-section" role="banner">
        <a href="/" class="logo" aria-label="IdeaForum — Go to homepage">
          <!--
            IdeaForum wordmark: the missing "E" in "IDEA" rendered as a dashed outline,
            a visual nod to the 404 "not found" concept.
          -->
          <svg class="logo-svg" viewBox="0 0 340 60" fill="none" xmlns="http://www.w3.org/2000/svg" aria-hidden="true" focusable="false">
            <!-- I -->
            <text x="0" y="50" font-family="Inter, sans-serif" font-size="52" font-weight="700" fill="#EB0028">I</text>
            <!-- D -->
            <text x="22" y="50" font-family="Inter, sans-serif" font-size="52" font-weight="700" fill="#EB0028">D</text>
            <!-- E (dashed outline — the "missing" letter) -->
            <rect x="72" y="4" width="30" height="48" rx="1"
              fill="none"
              stroke="#EB0028"
              stroke-width="2.5"
              stroke-dasharray="5 3" />
            <!-- A -->
            <text x="108" y="50" font-family="Inter, sans-serif" font-size="52" font-weight="700" fill="#EB0028">A</text>
            <!-- Separator space -->
            <!-- F -->
            <text x="168" y="50" font-family="Inter, sans-serif" font-size="52" font-weight="700" fill="#121212">F</text>
            <!-- O -->
            <text x="198" y="50" font-family="Inter, sans-serif" font-size="52" font-weight="700" fill="#121212">O</text>
            <!-- R -->
            <text x="235" y="50" font-family="Inter, sans-serif" font-size="52" font-weight="700" fill="#121212">R</text>
            <!-- U -->
            <text x="266" y="50" font-family="Inter, sans-serif" font-size="52" font-weight="700" fill="#121212">U</text>
            <!-- M -->
            <text x="298" y="50" font-family="Inter, sans-serif" font-size="52" font-weight="700" fill="#121212">M</text>
          </svg>
        </a>
      </header>

      <!-- Error Message -->
      <section class="error-message-section" aria-labelledby="error-heading">
        <h1 class="apology" id="error-heading">Sorry, we can't find that.</h1>
        <p class="suggestion">Perhaps we can help you find the content you're looking for:</p>
      </section>

      <!-- Search -->
      <section class="search-section" aria-label="Search IdeaForum">
        <form class="search-form" role="search" action="/search" method="GET" id="search-form">
          <label for="search-input" class="sr-only">Search IdeaForum</label>
          <input
            type="search"
            id="search-input"
            name="q"
            class="search-input"
            placeholder="Search IdeaForum..."
            autocomplete="off"
            aria-label="Search IdeaForum"
          />
          <button type="submit" class="search-btn" aria-label="Submit search">
            <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">
              <circle cx="11" cy="11" r="8"/>
              <line x1="21" y1="21" x2="16.65" y2="16.65"/>
            </svg>
          </button>
        </form>
      </section>

      <!-- Error Code -->
      <section class="error-code-section" aria-label="Error code">
        <div class="error-code-bar">
          <span class="error-code-text">HTTP Error 404</span>
        </div>
        <div class="section-divider" role="separator" aria-hidden="true"></div>
      </section>

      <!-- Next Steps -->
      <section class="next-steps-section" aria-labelledby="next-steps-heading">
        <h2 class="next-steps-heading" id="next-steps-heading">What's next?</h2>
        <nav class="nav-links" aria-label="Recovery navigation">
          <a href="/" class="nav-link">Go to the homepage</a>
          <a href="/help" class="nav-link">Visit our Help Desk</a>
        </nav>
      </section>

    </div>
  </main>

  <!-- ═══════════════════════════ COOKIE BANNER ═══════════════════════════ -->
  <div
    class="cookie-banner"
    id="cookie-banner"
    role="region"
    aria-label="Cookie consent"
    aria-live="polite"
  >
